module fsm
(
  input  logic        clk,
  input  logic        reset,

  input  logic        istream_val,
  output logic        istream_rdy,

  output logic        ostream_val,
  input  logic        ostream_rdy,

  //control signals
  output logic         b_mux_sel,
  output logic         a_mux_sel,
  output logic         result_mux_sel,
  output logic         result_en,
  output logic         add_mux_sel,

  input logic          b_lsb,
  input logic          b_zero,
  
  input logic         next_b_zero
);

typedef enum logic [1:0] { STATE_IDLE, STATE_CALC, STATE_DONE } state_e;
state_e state, next_state;

// sequential state register

always_ff @(posedge clk or posedge reset) begin
  if (reset) state <= STATE_IDLE;
  else       state <= next_state;
end

// state transition block
always_comb begin
  next_state = state;
  if (state == STATE_IDLE) begin
    if (istream_val & istream_rdy) begin
      next_state = STATE_CALC;
    end
  end
  else if (state == STATE_CALC) begin
    if (next_b_zero) begin
      next_state = STATE_DONE;
    end
  end

  else if (state == STATE_DONE) begin
    if (ostream_rdy) begin
      next_state = STATE_IDLE;
    end
  end
end
  
// output block, blue text and ostream logics
always_comb begin

  // defaults
  istream_rdy     = 1'b0;
  ostream_val     = 1'b0;

  b_mux_sel       = 1'b0;  
  a_mux_sel       = 1'b0;
  result_mux_sel  = 1'b0;  
  add_mux_sel     = 1'b0;  
  result_en       = 1'b0;

  unique case (state)
    STATE_IDLE : begin istream_rdy = 1'b1;
                b_mux_sel = istream_val & istream_rdy; 
                a_mux_sel = istream_val & istream_rdy;
                result_mux_sel = istream_val & istream_rdy;
                result_en = istream_val & istream_rdy;
  
    end
    STATE_CALC :begin b_mux_sel = 1'b0;
                a_mux_sel = 1'b0;
                result_mux_sel = 1'b0;
                add_mux_sel = b_lsb; 
                result_en = 1'b1;
    end
    STATE_DONE :begin 
      ostream_val = 1'b1;
      result_en = 1'b0;
    end
  endcase
end

endmodule


